//
// NkPdfGlyphList.cpp — nom de glyphe -> texte UTF-8, d'apres la Adobe Glyph
// List (AGL). C'est la cle qui rend LISIBLES les polices Type 1 des PDF
// dvips/LaTeX sans table /ToUnicode : leurs encodages (/Differences ou table
// en clair du programme) designent les caracteres par NOM (/space, /alpha...),
// et l'AGL publie ce que chaque nom represente.
//
// DONNEE PUBLIEE, PRISE TELLE QUELLE : table generee par script depuis
// glyphlist.txt (Adobe Type Tools, licence BSD-3-Clause,
// github.com/adobe-type-tools/agl-aglfn), JAMAIS retapee a la main — une
// transcription manuelle a deja produit un decalage d'indexation ailleurs
// dans ce depot. Voir THIRD_PARTY_LICENSES.md.
//
